#!/bin/bash
# nginxWebUI WAF rule tuning watcher (E-395). Started in the background by nwu-start.sh; polls the shared volume
# /nwu-waf every NWU_WAF_POLL seconds (default 3).
#   request          apply id written by nginxWebUI after custom.yaml; applied when it differs from processed
#   custom.yaml      the appsec-config generated by nginxWebUI
#   result.json      {id, status: ok|failed, message, at} written back here
#   last-good.yaml   the last config that was applied successfully; the container always starts with the default
#                    config and this watcher applies last-good.yaml once LAPI is up
#   processed        last handled apply id
#   applying         apply id being reloaded; a failed reload makes crowdsec exit, the next start reports it
#   startup-applying set while last-good.yaml is reloaded at start; if crowdsec dies then, last-good.yaml is dropped
# A config is only reloaded after `crowdsec -t` accepts it; otherwise the previous one is restored.
set -u
dir=/nwu-waf
active=/etc/crowdsec/appsec-configs/nwu-custom.yaml
cfg=/etc/crowdsec/config.yaml
poll="${NWU_WAF_POLL:-3}"

log() { echo "nwu-waf: $*" >&2; }

# write_result <id> <ok|failed> <message>
write_result() {
  ID="$1" ST="$2" MSG="$3" AT="$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    yq -n -o=json -I=0 '.id = strenv(ID) | .status = strenv(ST) | .message = strenv(MSG) | .at = strenv(AT)' \
    > "$dir/result.json.tmp" && mv -f "$dir/result.json.tmp" "$dir/result.json"
  echo "$1" > "$dir/processed"
}

# fail_reason <crowdsec -t output> : the last 2 level=fatal/level=error lines, reduced to their msg="..." text (the whole
# line when it has none); without such lines the last 3 non-empty lines. At most 500 characters.
fail_reason() {
  r="$(printf '%s\n' "$1" | grep -E 'level=(fatal|error)' | tail -n 2 \
    | sed -E 's/^.*msg="//; s/" [a-z_]+=.*$//; s/"$//; s/\\"/"/g' | tr '\n' ' ')"
  [ -n "$(printf %s "$r" | tr -d " ")" ] || r="$(printf '%s\n' "$1" | grep -v '^[[:space:]]*$' | tail -n 3 | tr '\n' ' ')"
  printf '%s' "$r" | cut -c1-500
}

# apply <file> <id> : makes <file> the active config. Empty id = start-up reapply of last-good.yaml (no result.json).
apply() {
  src="$1"
  id="$2"
  cp -f "$active" /tmp/nwu-prev.yaml
  cp -f "$src" "$active"
  if ! out="$(crowdsec -c "$cfg" -t 2>&1)"; then
    cp -f /tmp/nwu-prev.yaml "$active"
    msg="$(fail_reason "$out")"
    log "config test failed, previous config restored: $msg"
    [ -n "$id" ] && write_result "$id" failed "$msg"
    return 1
  fi
  pid="$(pgrep -o -x crowdsec)"
  if [ -z "$pid" ]; then
    cp -f /tmp/nwu-prev.yaml "$active"
    [ -n "$id" ] && write_result "$id" failed "crowdsec process not found"
    return 1
  fi
  if [ -n "$id" ]; then echo "$id" > "$dir/applying"; else touch "$dir/startup-applying"; fi
  kill -HUP "$pid"
  sleep 5
  rm -f "$dir/applying" "$dir/startup-applying"
  if ! kill -0 "$pid" 2>/dev/null; then
    [ -n "$id" ] && write_result "$id" failed "crowdsec exited during reload"
    return 1
  fi
  cp -f "$active" "$dir/last-good.yaml"
  [ -n "$id" ] && write_result "$id" ok ""
  log "applied ${id:-last-good.yaml}"
  return 0
}

wait_lapi() {
  i=0
  while [ "$i" -lt 60 ]; do
    cscli lapi status >/dev/null 2>&1 && return 0
    i=$((i + 1))
    sleep 2
  done
  return 1
}

mkdir -p "$dir"
wait_lapi || log "LAPI not ready after 120s, watching anyway"
if [ -f "$dir/startup-applying" ]; then
  log "crowdsec died while reapplying last-good.yaml at start, dropping it"
  mv -f "$dir/last-good.yaml" "$dir/last-good.broken.yaml" 2>/dev/null || true
  rm -f "$dir/startup-applying"
fi
if [ -f "$dir/applying" ]; then
  id="$(tr -d '[:space:]' < "$dir/applying")"
  rm -f "$dir/applying"
  write_result "$id" failed "crowdsec could not reload this config and restarted; the previous settings are back in use"
fi
if [ -f "$dir/last-good.yaml" ] && ! cmp -s "$dir/last-good.yaml" "$active"; then
  apply "$dir/last-good.yaml" "" || log "last-good.yaml rejected, keeping the default config"
fi
while true; do
  if [ -f "$dir/request" ] && [ -f "$dir/custom.yaml" ]; then
    id="$(tr -d '[:space:]' < "$dir/request")"
    done_id="$(tr -d '[:space:]' < "$dir/processed" 2>/dev/null || true)"
    if [ -n "$id" ] && [ "$id" != "$done_id" ]; then
      cp -f "$dir/custom.yaml" /tmp/nwu-new.yaml
      apply /tmp/nwu-new.yaml "$id" || true
    fi
  fi
  sleep "$poll"
done
